import torch
import torch.nn as nn

class TanhRNN(nn.Module):
    def __init__(self, input_size, hidden_size):
        super(TanhRNN, self).__init__()
        self.hidden_size = hidden_size
        self.tanh = nn.Tanh()
        self.rnn = nn.RNN(input_size, hidden_size, 1, nonlinearity='tanh')

    def forward(self, input):
        output, hidden = self.rnn(input)
        return self.tanh(output)

import norse
import norse.torch as nts

class LIFRNN(nts.SequentialState):
    def __init__(self, input_size, hidden_size):
        super(LIFRNN, self).__init__(
            nts.LILinear(input_size, hidden_size, batch_size=1),
            nts.LiLIF(),
            nts.LILinear(hidden_size, hidden_size, batch_size=1),
            nts.LiLIF()
        )

import torch
import norse.torch as norse

class SNNClassifier:
    def __init__(self, input_size, hidden_size, num_classes):
        self.hidden = norse.LIFCell(input_size, hidden_size)
        self.output = norse.LinearCell(hidden_size, num_classes)

    def forward(self, x):
        x = self.hidden(x)
        x = self.output(x)
        return x

def surrogate_gradient_training(model, train_loader, criterion, optimizer, num_epochs):
    for epoch in range(num_epochs):
        for i, (inputs, labels) in enumerate(train_loader):
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
        print(f"Epoch {epoch+1}/{num_epochs} | Loss: {loss.item()}")
